const htmls = [];
try { htmls.push($('Fetch page 1').first().json.data || ''); } catch (e) { htmls.push(''); }
try { htmls.push($('Fetch page 2').first().json.data || ''); } catch (e) { htmls.push(''); }

const out = [];
let totalCards = 0;
const seen = new Set();
for (const html of htmls) {
  if (typeof html !== 'string' || !html) continue;
  const blocks = html.split('id="filter-item-').slice(1);
  totalCards += blocks.length;
  for (const b of blocks) {
    const id = (b.match(/^(\d+)/) || [])[1];
    if (!id || seen.has(id)) continue;
    seen.add(id);
    const href = (b.match(/href="(\/fr\/louer\/[^"]+)"/) || [])[1];
    const decode = s => (s || '').replace(/&#(\d+);/g, (_, c) => String.fromCharCode(c)).replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#x27;|&apos;/g, "'").trim();
    const priceRaw = decode((b.match(/<strong class="title">\s*([^<]+)</) || ['',''])[1]);
    const otype = decode((b.match(/<p class="object-type">([^<]+)</) || ['',''])[1]);
    const addr = decode((b.match(/<p class="object-type">[^<]*<\/p>\s*<p>([^<]+)</) || ['',''])[1]);
    const m2m = (b.match(/<span class="space">(\d+)\s*m</) || [])[1];
    const rm = otype.match(/(\d+(?:[.,]\d)?)\s*pi[eè]ce/i);
    const rooms = rm ? parseFloat(rm[1].replace(',', '.')) : null;
    if (rooms === null || rooms < 2.5 || rooms > 3.5) continue;
    let rent_net = null, charges = null, rent_gross = null;
    const base = priceRaw.match(/CHF\s*([\d']+)/);
    if (base) {
      const v = parseInt(base[1].replace(/'/g, ''), 10);
      const ch = priceRaw.match(/\+\s*([\d']+)/);
      if (ch) { rent_net = v; charges = parseInt(ch[1].replace(/'/g, ''), 10); rent_gross = v + charges; }
      else if (/compris/i.test(priceRaw)) { rent_gross = v; }
      else { rent_net = v; }
    }
    const commune = (addr.split(',')[0] || 'Bulle').trim();
    const imgRel = (b.match(/data-src="(\/Medias\/[^"]+\/NewThumbnail\/[^"]+\.jpg)"/i) || [])[1];
    const images = imgRel
      ? ['https://www.immobilier.ch' + imgRel.replace('/NewThumbnail/', '/Big/'), 'https://www.immobilier.ch' + imgRel]
      : [];
    out.push({ json: {
      source: 'immobilier',
      source_id: id,
      url: href ? 'https://www.immobilier.ch' + href : null,
      title: otype + (addr ? ' — ' + addr : ''),
      rent_net, rent_gross, charges,
      rooms, m2: m2m ? parseInt(m2m, 10) : null,
      commune, address_raw: addr || null,
      description: priceRaw, cross_key: null, published_at: null,
      images
    }});
  }
}
if (totalCards === 0) {
  throw new Error('immobilier.ch: 0 listing cards parsed on Bulle search — page structure changed or request blocked');
}
return out;
